<?php
require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/PaymentGateway.php';
$items=get_cart_items($pdo);$subtotal=cart_total($items);$user=current_user();if(!$items){header('Location: '.site_url('cart.php'));exit;}
$errors=[];$couponCode=(string)($_SESSION['coupon_code']??'');$coupon=calculate_coupon($pdo,$couponCode,$subtotal);if($coupon['error']){unset($_SESSION['coupon_code']);$couponCode='';$coupon=['discount'=>0,'code'=>null,'error'=>null];}
$shippingFee=max(0,(int)setting('shipping_fee','0'));$freeThreshold=max(0,(int)setting('free_shipping_threshold','0'));$shipping=($freeThreshold>0&&$subtotal>=$freeThreshold)?0:$shippingFee;$discount=(int)$coupon['discount'];$total=max(0,$subtotal-$discount+$shipping);
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'order');
 if($action==='coupon'){ $code=trim((string)($_POST['coupon_code']??''));$c=calculate_coupon($pdo,$code,$subtotal);if($c['error']){flash('error',$c['error']);}else{$_SESSION['coupon_code']=$c['code'];flash('success',$c['code']?'کد تخفیف اعمال شد.':'کد تخفیف حذف شد.');}header('Location: '.site_url('checkout.php'));exit; }
 $name=trim((string)($_POST['name']??''));$phone=trim((string)($_POST['phone']??''));$email=trim((string)($_POST['email']??''));$address=trim((string)($_POST['address']??''));$notes=trim((string)($_POST['notes']??''));$payOnline=isset($_POST['pay_online']);
 if(mb_strlen($name)<2)$errors[]='نام گیرنده را وارد کنید.';if(!preg_match('/^[0-9+\-\s()]{8,20}$/',$phone))$errors[]='شماره تماس معتبر وارد کنید.';if($address==='')$errors[]='آدرس کامل تحویل الزامی است.';if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='ایمیل معتبر نیست.';
 if(isset($_FILES['design_file'])&&($_FILES['design_file']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE&&($_FILES['design_file']['size']??0)>(int)($config['upload_max_bytes']??5242880)*4)$errors[]='حجم فایل طرح بیش از حد مجاز است.';
 $coupon=calculate_coupon($pdo,(string)($_SESSION['coupon_code']??''),$subtotal);if($coupon['error']){$errors[]=$coupon['error'];$discount=0;$couponCode='';}else{$discount=(int)$coupon['discount'];$couponCode=(string)($coupon['code']??'');}$total=max(0,$subtotal-$discount+$shipping);
 if(!$errors){try{
  $pdo->beginTransaction();$publicCode=bin2hex(random_bytes(12));
  $st=$pdo->prepare("INSERT INTO orders(user_id,public_code,customer_name,phone,email,address,notes,total_amount,status,payment_status,coupon_code,discount_amount,shipping_amount,created_at) VALUES(?,?,?,?,?,?,?,?,'pending','unpaid',?,?,?,NOW())");$st->execute([$user['id']??null,$publicCode,$name,$phone,$email?:null,$address,$notes,$total,$couponCode?:null,$discount,$shipping]);$orderId=(int)$pdo->lastInsertId();
  $line=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,unit_price,quantity,line_total,customization_json) VALUES(?,?,?,?,?,?,?)');
  foreach($items as $p){$custom=json_encode($p['selected_options']??[],JSON_UNESCAPED_UNICODE);$line->execute([$orderId,$p['id'],$p['name'],$p['unit_price']??$p['price'],$p['qty'],$p['line_total'],$custom]);}
  if($couponCode){$pdo->prepare('UPDATE coupons SET used_count=used_count+1 WHERE code=?')->execute([$couponCode]);}
  $pdo->commit();
  if(isset($_FILES['design_file'])&&($_FILES['design_file']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){try{$file=safe_upload($_FILES['design_file'],['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'],'designs',min(20*1024*1024,(int)($config['upload_max_bytes']??5242880)*4));$pdo->prepare('INSERT INTO order_files(order_id,original_name,stored_name,mime_type,file_size,created_at) VALUES(?,?,?,?,?,NOW())')->execute([$orderId,basename((string)$_FILES['design_file']['name']),$file['name'],$file['mime'],$file['size']]);}catch(Throwable $e){flash('error','سفارش ثبت شد، اما فایل طرح ذخیره نشد: '.$e->getMessage());}}
  unset($_SESSION['cart'],$_SESSION['cart_options'],$_SESSION['coupon_code']);
  if($payOnline){try{$gateway=new PaymentGateway($config);$amountRial=$total*10;$callback=site_url($config['payment']['callback_path']??'payment-callback.php');$payment=$gateway->createPayment($orderId,$amountRial,$callback,'پرداخت سفارش ADVERSING '.$publicCode,$email,$phone);$pdo->prepare("INSERT INTO payment_transactions(order_id,provider,authority,amount_rial,status,raw_response,created_at) VALUES(?,?,?,?,'created',?,NOW())")->execute([$orderId,'zarinpal',$payment['authority'],$amountRial,json_encode($payment['raw'],JSON_UNESCAPED_UNICODE)]);header('Location: '.$payment['url']);exit;}catch(Throwable $e){flash('error','سفارش ثبت شد، اما شروع پرداخت ناموفق بود: '.$e->getMessage());header('Location: '.site_url('order.php?code='.$publicCode));exit;}}
  flash('success','سفارش شما ثبت شد.');header('Location: '.site_url('order.php?code='.$publicCode));exit;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]='ثبت سفارش انجام نشد. تنظیمات دیتابیس را بررسی و دوباره تلاش کنید.';}}
}
$gateway=new PaymentGateway($config);$onlineReady=$gateway->isConfigured();render_header('ثبت سفارش');
