<?php if(!$user):?><div class="notice">برای ذخیره سفارش در حساب کاربری، <a href="<?=e(site_url('login.php?next=checkout.php'))?>">وارد شوید</a> یا <a href="<?=e(site_url('register.php'))?>">ثبت‌نام کنید</a>. امکان سفارش مهمان نیز وجود دارد.</div><?php endif;?>
