<div class="summary-lines"><p>جمع محصولات: <strong><?=money($subtotal)?></strong></p><p>تخفیف: <strong><?=money($discount)?></strong></p><p>هزینه ارسال: <strong><?=money($shipping)?></strong></p><h3>مبلغ نهایی: <span class="price"><?=money($total)?></span></h3></div>
<form method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="action" value="order"><div class="form-grid"><div class="form-group"><label>نام و نام خانوادگی *</label><input name="name" required value="<?=e($_POST['name']??($user['full_name']??''))?>"></div><div class="form-group"><label>شماره تماس *</label><input name="phone" required value="<?=e($_POST['phone']??($user['phone']??''))?>"></div><div class="form-group"><label>ایمیل</label><input type="email" name="email" value="<?=e($_POST['email']??($user['email']??''))?>"></div><div class="form-group full"><label>آدرس کامل تحویل *</label><textarea name="address" rows="3" required><?=e($_POST['address']??'')?></textarea></div><div class="form-group full"><label>توضیحات سفارش</label><textarea name="notes" rows="3"><?=e($_POST['notes']??'')?></textarea></div><div class="form-group full"><label>فایل طرح چاپ (PDF/JPG/PNG/WEBP)</label><input type="file" name="design_file" accept="application/pdf,image/jpeg,image/png,image/webp"></div></div><?php if($onlineReady):?><button class="btn" name="pay_online" value="1">ثبت سفارش و پرداخت آنلاین</button><?php else:?><div class="notice">درگاه هنوز پیکربندی نشده است. سفارش ثبت می‌شود ولی وجهی دریافت نمی‌شود. برای فعال‌سازی، شناسه پذیرنده را در config.php تنظیم و ابتدا در حالت آزمایشی تست کنید.</div><button class="btn">ثبت سفارش</button><?php endif;?></form></div></main><?php render_footer();
